import{_ as e,o as i,c as a,ag as s}from"./chunks/framework.NIGIbcGl.js";const g=JSON.parse('{"title":"Mitra Registrations Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"admin/mitra-registrations/index.md","filePath":"admin/mitra-registrations/index.md"}'),n={name:"admin/mitra-registrations/index.md"};function o(r,t,d,l,p,h){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="mitra-registrations-management-guide" tabindex="-1">Mitra Registrations Management Guide <a class="header-anchor" href="#mitra-registrations-management-guide" aria-label="Permalink to &quot;Mitra Registrations Management Guide&quot;">​</a></h1><p>Admin review and approval of <strong>Mitra</strong> (partner) self-serve registrations. Approval always issues a per-tier registration number and grants the tier&#39;s pricing access. <strong>Whether it also creates an Organization depends on the applicant</strong>, not on you — see <a href="#two-kinds-of-partner">Two kinds of partner</a>.</p><blockquote><h2 id="two-kinds-of-partner" tabindex="-1">Two kinds of partner <a class="header-anchor" href="#two-kinds-of-partner" aria-label="Permalink to &quot;Two kinds of partner&quot;">​</a></h2><p>The organization form on the registration (<code>companyName</code>) is <strong>optional</strong>, and it is the applicant who fills it in — not the admin. It decides the shape of the approval:</p><table tabindex="0"><thead><tr><th><code>companyName</code> on the registration</th><th>What approve creates</th></tr></thead><tbody><tr><td>present</td><td><strong>Organization</strong> + org SAR wallet; the account is promoted to <code>B2B</code>; the tier flags live on the org.</td></tr><tr><td><code>null</code></td><td><strong>No Organization, no org wallet.</strong> The account stays <code>B2C</code> and the tier + promo flags are written onto the <strong>user</strong>.</td></tr></tbody></table><p><strong>An individual partner with no Organization is not a bug.</strong> They are priced identically — a <code>B2C</code> user carrying <code>pricingTier: GOLD</code> gets the full special pricing set, because the per-user override outranks the organization axis in the pricing engine. There is nothing to fix and nothing to create by hand.</p><p>To find them on the users list, filter by <strong><code>?pricingTier=GOLD</code></strong>, not by <code>?specialCustomPricingEnabled=true</code> — that flag is org-only and does <strong>not</strong> describe these partners. See the <a href="/ahlaan-train-docs/admin/users/">Users guide</a>.</p></blockquote><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td>List</td><td><code>GET /admin/mitra-registrations</code></td></tr><tr><td>Get one</td><td><code>GET /admin/mitra-registrations/:id</code></td></tr><tr><td>Mark under review</td><td><code>POST /admin/mitra-registrations/:id/review</code></td></tr><tr><td>Approve</td><td><code>POST /admin/mitra-registrations/:id/approve</code></td></tr><tr><td>Reject</td><td><code>POST /admin/mitra-registrations/:id/reject</code></td></tr></tbody></table><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;/api/v1</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All endpoints require a JWT with the <code>ADMIN</code> role.</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;admin-jwt&gt;</span></span></code></pre></div><h2 id="status-workflow" tabindex="-1">Status Workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status Workflow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PENDING ─┬─&gt; UNDER_REVIEW ─┬─&gt; APPROVED  (terminal)</span></span>
<span class="line"><span>         │                 └─&gt; REJECTED ─&gt; PENDING (resubmit)</span></span>
<span class="line"><span>         ├─&gt; APPROVED</span></span>
<span class="line"><span>         └─&gt; REJECTED</span></span></code></pre></div><p><code>APPROVED</code> is terminal. Illegal transitions are rejected with <code>400</code>.</p><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="list-registrations" tabindex="-1">List registrations <a class="header-anchor" href="#list-registrations" aria-label="Permalink to &quot;List registrations&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /admin/mitra-registrations</code></p><p><strong>Query params:</strong> <code>status</code>, <code>tier</code>, <code>applicantType</code>, <code>search</code>, <code>page</code> (default 1), <code>limit</code> (default 10). <code>search</code> matches applicant name, email, company name, or registration number.</p><p><strong>Response:</strong> <code>200 OK</code></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GOLD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PENDING&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pagination&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;totalPages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="approve" tabindex="-1">Approve <a class="header-anchor" href="#approve" aria-label="Permalink to &quot;Approve&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /admin/mitra-registrations/:id/approve</code></p><p><strong>Request Body:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;adminNotes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Documents verified against source.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;depositConfirmed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>adminNotes</code></td><td>No</td><td>Free-text, recorded on the audit log.</td></tr><tr><td><code>depositConfirmed</code></td><td><strong>GOLD only</strong></td><td>Must be <code>true</code> to approve a <code>GOLD</code> registration — the admin confirms the 50,000 SAR deposit was received off-system. Ignored for <code>SILVER</code>. Recorded on the audit-log entry.</td></tr></tbody></table><p><strong>What happens (atomic transaction):</strong></p><ol><li><p>Assigns the next <strong>per-tier</strong> registration number (<code>MS.</code> / <code>MG.</code>). Both kinds of partner draw from the same per-tier counter.</p></li><li><p><strong>Then it branches on whether the registration carries a <code>companyName</code>:</strong></p><p><strong>Organization partner</strong> (<code>companyName</code> present):</p><ul><li>Creates an <strong>Organization</strong> + <strong>SAR Wallet</strong>.</li><li>Sets the tier&#39;s pricing fields on the org (<code>pricingTier</code> is the source of truth; <code>specialCustomPricingEnabled</code> is written as its deprecated mirror): <ul><li><strong>GOLD</strong> ⇒ <code>pricingTier = GOLD</code>, <code>specialCustomPricingEnabled = true</code>, <code>promoAccessEnabled = true</code></li><li><strong>SILVER</strong> ⇒ <code>pricingTier = SILVER</code>, <code>promoAccessEnabled = true</code></li></ul></li><li>Promotes the applicant account to a <code>B2B</code> member of the new org (and clears any per-user overrides, so the org flags govern).</li></ul><p><strong>Individual partner</strong> (<code>companyName</code> is <code>null</code>):</p><ul><li>Creates <strong>no Organization and no organization wallet</strong>.</li><li>Writes the tier onto the <strong>user</strong>: <code>promoAccessEnabled = true</code> plus <code>pricingTier = GOLD</code> or <code>SILVER</code>. The account <strong>stays <code>B2C</code></strong>.</li><li>The registration keeps <code>organizationId: null</code>.</li></ul></li><li><p>Sends the <code>mitra-registration-approved</code> email (the organization-code row is omitted for an individual partner).</p></li></ol><p><strong>Pre-conditions (else <code>400</code>):</strong> all required documents must be present — SPK + partnership for all, KTP for <code>INDIVIDUAL</code>, payment proof for <code>SILVER</code> and <code>GOLD</code>. Approving a <code>GOLD</code> registration also requires <code>depositConfirmed: true</code> — <strong>including an individual partner</strong>: the 50,000 SAR deposit is keyed on the tier, not on whether the applicant has a company.</p><p><strong>Conflicts (<code>409</code>):</strong> the linked account is an admin, is already <code>B2B</code>, already belongs to an organization, or <strong>already has an approved mitra registration</strong> (one approved registration per account, ever — this is the guard that stops an approved individual partner, who is still <code>B2C</code>, from being approved a second time and burning another registration number).</p><p><strong>Response:</strong> <code>201 Created</code> — the approved registration with its <code>registrationNumber</code>.</p><h3 id="reject" tabindex="-1">Reject <a class="header-anchor" href="#reject" aria-label="Permalink to &quot;Reject&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /admin/mitra-registrations/:id/reject</code></p><p><strong>Request Body:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rejectionReason&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SPK document is illegible. Please re-upload a clear scan.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;adminNotes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Second rejection for this applicant.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the rejected registration. A rejection email is sent to the applicant.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Tier is a stored label mapped to access flags on approval (Option A).</strong> The pricing engine is driven by those flags — on the <strong>organization</strong> for an organization partner, on the <strong>user</strong> for an individual partner. The stored tier drives numbering and the onboarding record. Manually toggling the flags later can drift from the recorded tier — the flags stay the source of truth for pricing.</li><li>The <strong>Gold 50,000 SAR deposit</strong> proof is captured as the payment proof, and the admin confirms receipt via <code>depositConfirmed</code> at approve time. The deposit stays <strong>manual / off-system</strong> — it is <strong>not</strong> credited to any wallet, and there is no deposit ledger or reconciliation table for it.</li><li><strong>Personal wallets are created at registration</strong>, not at approval. Every mitra applicant gets a personal SAR wallet when they submit, so an individual partner (who never receives an organization wallet) still has a working wallet.</li><li><strong>Invoices carry the partner identity either way.</strong> The <code>MS.</code>/<code>MG.</code> number and partner name are snapshotted onto every invoice — resolved from the owning organization when there is one, and from the user&#39;s own approved registration when there is not.</li></ul><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/admin/b2b-applications/">B2B Applications Management Guide</a></li><li><a href="/ahlaan-train-docs/admin/users/">Users Management Guide</a> — finding individual partners by tier</li></ul>`,40)])])}const k=e(n,[["render",o]]);export{g as __pageData,k as default};
